<?php
session_start();
$cfg = __DIR__ . '/config.php';
if (file_exists($cfg)) { header('Location: index.php'); exit; }

if ($_POST) {
    try {
        extract($_POST);
        $pdo = new PDO("mysql:host=$host;charset=utf8mb4", $user, $pass);
        $pdo->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);
        $pdo->exec("CREATE DATABASE IF NOT EXISTS `$name`");
        $pdo->exec("USE `$name`");
        
        // Criar TODAS as tabelas — IF NOT EXISTS garante reaproveitamento seguro
        $tables = array(
        "CREATE TABLE IF NOT EXISTS users (
            id INT AUTO_INCREMENT PRIMARY KEY,
            name VARCHAR(255) NOT NULL,
            email VARCHAR(255) NOT NULL UNIQUE,
            password VARCHAR(255) NOT NULL,
            created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
        ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",

        "CREATE TABLE IF NOT EXISTS events (
            id INT AUTO_INCREMENT PRIMARY KEY,
            title VARCHAR(255) NOT NULL,
            start_time TIME,
            end_time TIME,
            location VARCHAR(255),
            summary TEXT,
            photo VARCHAR(255),
            speaker_name VARCHAR(255),
            speaker_email VARCHAR(255),
            speaker_bio TEXT,
            speaker_photo VARCHAR(255),
            is_special TINYINT(1) DEFAULT 0,
            event_order INT DEFAULT 0,
            created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
            updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
        ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",

        "CREATE TABLE IF NOT EXISTS event_meta (
            id INT AUTO_INCREMENT PRIMARY KEY,
            event_id INT NOT NULL,
            meta_key VARCHAR(255) NOT NULL,
            meta_value LONGTEXT,
            INDEX idx_event_id (event_id),
            INDEX idx_meta_key (meta_key)
        ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",

        "CREATE TABLE IF NOT EXISTS participants (
            id INT AUTO_INCREMENT PRIMARY KEY,
            name VARCHAR(255) NOT NULL,
            email VARCHAR(255) NOT NULL,
            document VARCHAR(50),
            organization VARCHAR(255),
            phone VARCHAR(50),
            event_name VARCHAR(255),
            status ENUM('pending','confirmed','cancelled') DEFAULT 'pending',
            checkin_at DATETIME,
            cert_sent_at DATETIME,
            notes TEXT,
            qr_key VARCHAR(64) NOT NULL UNIQUE,
            created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
            INDEX idx_email (email),
            INDEX idx_qr_key (qr_key),
            INDEX idx_status (status)
        ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",

        "CREATE TABLE IF NOT EXISTS participant_meta (
            id INT AUTO_INCREMENT PRIMARY KEY,
            participant_id INT NOT NULL,
            meta_key VARCHAR(255) NOT NULL,
            meta_value LONGTEXT,
            INDEX idx_participant_id (participant_id),
            INDEX idx_meta_key (meta_key)
        ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",

        "CREATE TABLE IF NOT EXISTS grids (
            id INT AUTO_INCREMENT PRIMARY KEY,
            title VARCHAR(255) NOT NULL,
            selected_events TEXT,
            show_times TINYINT(1) DEFAULT 1,
            show_speakers TINYINT(1) DEFAULT 1,
            show_types TINYINT(1) DEFAULT 1,
            show_photos TINYINT(1) DEFAULT 1,
            visible_columns TEXT,
            created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
        ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",

        "CREATE TABLE IF NOT EXISTS activity_types (
            id INT AUTO_INCREMENT PRIMARY KEY,
            name VARCHAR(255) NOT NULL,
            slug VARCHAR(255) NOT NULL UNIQUE,
            parent_id INT,
            INDEX idx_parent_id (parent_id)
        ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",

        "CREATE TABLE IF NOT EXISTS custom_fields (
            id INT AUTO_INCREMENT PRIMARY KEY,
            field_key VARCHAR(100) NOT NULL UNIQUE,
            field_label VARCHAR(255) NOT NULL,
            field_type VARCHAR(50) NOT NULL,
            field_options TEXT,
            field_required TINYINT(1) DEFAULT 0,
            field_show_in_table TINYINT(1) DEFAULT 0,
            field_order INT DEFAULT 0,
            context ENUM('event','participant') DEFAULT 'event'
        ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",

        "CREATE TABLE IF NOT EXISTS settings (
            setting_key VARCHAR(100) PRIMARY KEY,
            setting_value LONGTEXT,
            autoload TINYINT(1) DEFAULT 1
        ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",

        "CREATE TABLE IF NOT EXISTS cert_files (
            id INT AUTO_INCREMENT PRIMARY KEY,
            ref_type ENUM('speaker','participant') NOT NULL,
            ref_id INT NOT NULL,
            ref_name VARCHAR(255),
            file_path VARCHAR(512),
            created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
        ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
        "CREATE TABLE IF NOT EXISTS certificates (
            id INT AUTO_INCREMENT PRIMARY KEY,
            cert_type ENUM('speaker','participant') NOT NULL,
            template_html LONGTEXT,
            template_css TEXT,
            bg_image LONGTEXT,
            positions TEXT,
            variables TEXT,
            created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
            updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
        ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4"
        );

        foreach ($tables as $sql) {
            $pdo->exec($sql);
        }

        // INSERT IGNORE — não duplica se já existirem (reaproveitamento seguro)
        $pdo->exec("INSERT IGNORE INTO activity_types (name, slug) VALUES
            ('Palestra', 'palestra'),
            ('Oficina', 'oficina'),
            ('Mesa Redonda', 'mesa-redonda'),
            ('Workshop', 'workshop'),
            ('Painel', 'painel')");

        $pdo->exec("INSERT IGNORE INTO settings (setting_key, setting_value) VALUES
            ('site_name', 'Bienenstock'),
            ('version', '0.001')");

        // Salvar email do admin como remetente/destinatário padrão
        $pdo->prepare("INSERT INTO settings (setting_key, setting_value) VALUES ('from_email', ?) ON DUPLICATE KEY UPDATE setting_value=?")
            ->execute(array($admin_email, $admin_email));
        
        // Criar admin — INSERT IGNORE evita erro se o email já existir (reinstalação)
        $pw = password_hash($admin_pass, PASSWORD_DEFAULT);
        $pdo->prepare("INSERT IGNORE INTO users (name,email,password) VALUES (?,?,?)")
            ->execute(array($admin_name, $admin_email, $pw));
        
        // Salvar config
        $config_content = "<?php\n\$host=" . var_export($host,true) . ";\n\$name=" . var_export($name,true) . ";\n\$user=" . var_export($user,true) . ";\n\$pass=" . var_export($pass,true) . ";\n";
        
        // Tenta gravar config.php — múltiplas estratégias para máxima compatibilidade
        $config_saved = false;
        
        // Estratégia 1: gravação direta
        if (@file_put_contents($cfg, $config_content) !== false) {
            $config_saved = true;
        }
        
        // Estratégia 2: ajustar permissão da pasta e tentar novamente
        if (!$config_saved) {
            @chmod(__DIR__, 0755);
            if (@file_put_contents($cfg, $config_content) !== false) {
                $config_saved = true;
            }
        }
        
        // Estratégia 3: tentar com permissão mais aberta (último recurso)
        if (!$config_saved) {
            @chmod(__DIR__, 0777);
            if (@file_put_contents($cfg, $config_content) !== false) {
                $config_saved = true;
                @chmod(__DIR__, 0755); // Restaurar para 755 após gravar
            }
        }
        
        if (!$config_saved) {
            // Não conseguiu gravar — guarda os dados na sessão e exibe para o usuário criar manualmente
            $_SESSION['config_content'] = $config_content;
            $_SESSION['install_done'] = true;
            $_SESSION['flash_ok'] = 'Banco de dados configurado! Siga o passo abaixo para finalizar.';
        } else {
            $_SESSION['flash_ok'] = 'Sistema instalado com sucesso! 10 tabelas criadas.';
        }
        
        // Criar pasta uploads com permissão segura
        $uploads_dir = __DIR__ . '/uploads';
        // uploads/ precisa de permissão de escrita para receber arquivos
        if (!is_dir($uploads_dir)) {
            @mkdir($uploads_dir, 0775, true);
            if (!is_dir($uploads_dir)) { @mkdir($uploads_dir, 0777, true); }
        }
        // Garantir que é gravável mesmo se já existia com permissão errada
        if (!is_writable($uploads_dir)) { @chmod($uploads_dir, 0775); }
        if (!is_writable($uploads_dir)) { @chmod($uploads_dir, 0777); }
        
        // Criar .htaccess de segurança na pasta uploads
        $htaccess = $uploads_dir . '/.htaccess';
        if (!file_exists($htaccess)) {
            $htaccess_content  = "# Bloquear execução de scripts PHP e outros\n";
            $htaccess_content .= "<FilesMatch \"\\.(php|php3|php4|php5|phtml|pl|py|jsp|asp|sh|cgi)\\$\">\n";
            $htaccess_content .= "    Order Deny,Allow\n";
            $htaccess_content .= "    Deny from all\n";
            $htaccess_content .= "</FilesMatch>\n";
            @file_put_contents($htaccess, $htaccess_content);
        }
        
        // Se salvou config automaticamente, redireciona direto para o sistema
        if ($config_saved) {
            header('Location: index.php');
            exit;
        }
        // Caso contrário, exibe as instruções para criação manual (continua para o HTML)
    } catch (Exception $e) {
        $err = $e->getMessage();
    }
}
?>
